async function runSlashCommand(
  host: SpotlightHost,
  document: Document,
  descriptor: SpotlightCommandDescriptor,
  name: string,
): Promise<void> {
  const commands = host.commands
  const sessionId = host.sessions.list.getSnapshot().current
