      "path": "package.json",
      "content": "{\n  \"name\": \"@0xsline/dsh-spotlight\",\n  \"description\": \"Keyboard-first command palette for DeepSeek Harness Web\",\n  \"version\": \"0.0.2\",\n  \"type\": \"module\",\n  \"packageManager\": \"pnpm@11.7.0\",\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"scripts\": {\n    \"build\": \"tsc -b && tsdown\",\n    \"test\": \"vitest run\",\n    \"typecheck\": \"tsc -b --pretty false && tsc -p tsconfig.vitest.json --pretty false\",\n    \"verify:self-contained\": \"node scripts/verify-self-contained.mjs\",\n    \"prepare\": \"node scripts/prepare.mjs\",\n    \"extract:patch\": \"node scripts/extract-patch.mjs\",\n    \"patch:host\": \"bash scripts/patch.sh\"\n  },\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./invariant\": {\n      \"types\": \"./lib/types/invariant.d.ts\",\n      \"default\": \"./lib/invariant.js\"\n    },\n    \"./src/*\": \"./src/*\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/invariant.js\",\n    \"lib/client.js\",\n    \"lib/types/**/*.d.ts\",\n    \"lib/types/**/*.d.ts.map\",\n    \"src\",\n    \"cordis.patch.yml\"\n  ],\n  \"license\": \"MIT\",\n  \"peerDependencies\": {\n    \"cordis\": \"^4.0.0-rc.7\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1\"\n  },\n  \"devDependencies\": {\n    \"@cordisjs/plugin-loader\": \"^1.0.0-rc.5\",\n    \"@types/node\": \"^22.20.0\",\n    \"cordis\": \"^4.0.0-rc.7\",\n    \"happy-dom\": \"^20.11.2\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1\",\n    \"tsdown\": \"^0.22.2\",\n    \"typescript\": \"^6.0.3\",\n    \"unrun\": \"^0.3.1\",\n    \"vitest\": \"^4.1.8\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-runtime\"\n      ]\n    }\n  }\n}\n"
