      "path": "src/spotlight/discovery.ts",
      "content": "import type { SearchCandidate } from './search.ts'\nimport type {\n  SpotlightCommandDescriptor, SpotlightHost, SpotlightPluginEntry, SpotlightSessionSummary,\n} from './host.ts'\n\n/** A searchable operation backed by a DSH Web host service or the current page. */\nexport interface SpotlightAction extends SearchCandidate {\n  run(): void\n}\n\nconst ACTIONABLE_SELECTOR = 'a[href], button, [role=\"button\"], [role=\"menuitem\"], [role=\"option\"], [role=\"tab\"]'\nconst SPOTLIGHT_ROOT_SELECTOR = '[data-dsh-spotlight-root]'\nconst SETTINGS_LABEL = new RegExp('^(?:settings?|设置)$', 'i')\nconst PLUGINS_LABEL = new RegExp('^(?:plugins?|插件)$', 'i')\nconst NEW_CHAT_LABEL = new RegExp('^(?:new (?:chat|session|conversation)|新建(?:会话|对话|聊天))$', 'i')\n/** Host command names are lowercase ASCII with letters, digits, `_` or `-`. */\nconst COMMAND_NAME = new RegExp('^[a-z0-9_-]{1,80}$')\n\nfunction belongsToSpotlight(element: HTMLElement): boolean {\n  return element.closest(SPOTLIGHT_ROOT_SELECTOR) !== null\n}\n\nfunction labelOf(element: HTMLElement): string {\n  return (\n    element.getAttribute('aria-label')\n    ?? element.getAttribute('title')\n    ?? element.textContent\n    ?? ''\n  ).replace(new RegExp('\\\\s+', 'g'), ' ').trim()\n}\n\nfunction actionable(document: Document): HTMLElement[] {\n  return [...document.querySelectorAll<HTMLElement>(ACTIONABLE_SELECTOR)]\n    .filter(element => !belongsToSpotlight(element) && element.getClientRects().length > 0)\n}\n\nfunction firstAction(document: Document, pattern: RegExp): HTMLElement | undefined {\n  return actionable(document).find(element =>\n    pattern.test(labelOf(element)) || pattern.test(element.getAttribute('href') ?? ''))\n}\n\nfunction composerOf(document: Document): HTMLElement | undefined {\n  return [...document.querySelectorAll<HTMLElement>('textarea, [contenteditable=\"true\"], [role=\"textbox\"]')]\n    .find(element => element.getAttribute('aria-hidden') !== 'true')\n}\n\n/** Insert a command line into the composer so the native slash pipeline owns the rest. */\nfunction insertCommand(document: Document, command: string): void {\n  const composer = composerOf(document)\n  if (composer === undefined) return\n  if (composer instanceof HTMLInputElement || composer instanceof HTMLTextAreaElement) {\n    composer.value = command\n  } else {\n    composer.textContent = command\n  }\n  composer.dispatchEvent(new Event('input', { bubbles: true }))\n  composer.focus()\n}\n\nfunction chatScroller(document: Document): HTMLElement | undefined {\n  let element = document.querySelector<HTMLElement>('[data-chat-flow=\"\"]')?.parentElement\n  while (element !== null && element !== undefined) {\n    const overflow = getComputedStyle(element).overflowY\n    if (overflow === 'auto' || overflow === 'scroll') return element\n    element = element.parentElement\n  }\n  return undefined\n}\n\nfunction unique(actions: SpotlightAction[]): SpotlightAction[] {\n  const seen = new Set<string>()\n  return actions.filter(action => {\n    const key = `${action.kind}:${action.id}`\n    if (seen.has(key)) return false\n    seen.add(key)\n    return true\n  })\n}\n\n/** Wait for an actionable element matching the predicate, without a fixed sleep. */\nfunction waitForActionable(\n  document: Document,\n  predicate: (element: HTMLElement) => boolean,\n  timeoutMs: number,\n): Promise<HTMLElement | undefined> {\n  const existing = actionable(document).find(predicate)\n  if (existing !== undefined) return Promise.resolve(existing)\n  const window = document.defaultView\n  if (window === null) return Promise.resolve(undefined)\n  return new Promise(resolve => {\n    let timer = 0\n    const observer = new window.MutationObserver(() => {\n      const found = actionable(document).find(predicate)\n      if (found === undefined) return\n      observer.disconnect()\n      window.clearTimeout(timer)\n      resolve(found)\n    })\n    observer.observe(document.body, { childList: true, subtree: true })\n    timer = window.setTimeout(() => {\n      observer.disconnect()\n      resolve(undefined)\n    }, timeoutMs)\n  })\n}\n\n/** Open the Web settings surface and switch to the installed-plugins section. */\nexport async function openPluginSettings(document: Document): Promise<void> {\n  const settings = firstAction(document, SETTINGS_LABEL)\n  if (settings === undefined) return\n  settings.click()\n  const plugins = await waitForActionable(document, element => PLUGINS_LABEL.test(labelOf(element)), 2000)\n  plugins?.click()\n}\n\n/** Immediately available operations read from the current page structure. */\nfunction builtInActions(document: Document): SpotlightAction[] {\n  const actions: SpotlightAction[] = []\n  const composer = composerOf(document)\n  if (composer !== undefined) {\n    actions.push({\n      id: 'focus-composer', kind: 'action', title: '聚焦输入框',\n      detail: 'Focus message composer', keywords: ['input', 'prompt', '输入'],\n      run: () => { composer.focus() },\n    })\n  }\n\n  const newChat = firstAction(document, NEW_CHAT_LABEL)\n  if (newChat !== undefined) {\n    actions.push({\n      id: 'new-chat', kind: 'action', title: '新建会话', detail: 'New conversation',\n      keywords: ['chat', 'session', 'conversation'], run: () => { newChat.click() },\n    })\n  }\n\n  const settings = firstAction(document, SETTINGS_LABEL)\n  if (settings !== undefined) {\n    actions.push({\n      id: 'open-plugins', kind: 'action', title: '打开插件设置', detail: 'Open installed plugin settings',\n      keywords: ['settings', 'extensions', '插件'],\n      run: () => { void openPluginSettings(document) },\n    })\n  }\n\n  const scroller = chatScroller(document)\n  if (scroller !== undefined) {\n    actions.push(\n      {\n        id: 'chat-top', kind: 'action', title: '跳到会话开头', detail: 'Jump to oldest message',\n        keywords: ['top', 'first', '开头'], run: () => { scroller.scrollTo({ top: 0, behavior: 'smooth' }) },\n      },\n      {\n        id: 'chat-bottom', kind: 'action', title: '跳到会话末尾', detail: 'Jump to newest message',\n        keywords: ['bottom', 'latest', '末尾'], run: () => { scroller.scrollTo({ top: scroller.scrollHeight, behavior: 'smooth' }) },\n      },\n    )\n  }\n  return actions\n}\n\n/** Interface operations: elements that carry an explicit label or are tabs. */\nfunction interfaceActions(document: Document): SpotlightAction[] {\n  const excluded = new RegExp('^(?:new (?:chat|session|conversation)|新建(?:会话|对话|聊天)|send message|发送消息|close|关闭(?:详情)?|commands?|命令)$', 'i')\n  return actionable(document).flatMap(element => {\n    const explicitLabel = element.getAttribute('aria-label') ?? element.getAttribute('title')\n    if (explicitLabel === null && element.getAttribute('role') !== 'tab') return []\n    const title = explicitLabel?.trim() || labelOf(element)\n    if (title === '' || title.length > 80 || excluded.test(title)) return []\n    if (element.getAttribute('aria-disabled') === 'true' || (element instanceof HTMLButtonElement && element.disabled)) return []\n    return [{\n      id: `ui:${title}`,\n      kind: 'action' as const,\n      title,\n      detail: '界面操作 · UI action',\n      keywords: [element.getAttribute('href') ?? ''],\n      run: () => { element.click() },\n    }]\n  })\n}\n\n/** Recent sessions straight from the host sessions service, newest order preserved. */\nfunction sessionActions(host: SpotlightHost): SpotlightAction[] {\n  const snapshot = host.sessions.list.getSnapshot()\n  return snapshot.ids.flatMap(id => {\n    const session: SpotlightSessionSummary | undefined = snapshot.byId[id]\n    if (session === undefined || session.blank === true) return []\n    const detail = [\n      session.cwd,\n      session.agentPreset !== undefined ? `Preset: ${session.agentPreset}` : undefined,\n      session.running ? '运行中' : undefined,\n    ].filter((part): part is string => part !== undefined).join(' · ') || '最近会话 · Recent session'\n    return [{\n      id: `session:${session.id}`,\n      kind: 'session',\n      title: session.displayTitle,\n      detail,\n      keywords: [session.id, session.cwd ?? ''],\n      run: () => { host.sessions.open(session.id) },\n    }]\n  })\n}\n\n/** Dispatch one bare host command; argued commands fall through to the composer claim path. */\nasync function runSlashCommand(\n  host: SpotlightHost,\n  document: Document,\n  descriptor: SpotlightCommandDescriptor,\n  name: string,\n): Promise<void> {\n  const commands = host.commands\n  const sessionId = host.sessions.list.getSnapshot().current\n  if (commands === undefined || sessionId === undefined || descriptor.input !== undefined) {\n    insertCommand(document, `/${name} `)\n    return\n  }\n  try {\n    const result = await commands.execute(sessionId, `/${name}`)\n    if (!result.ok || result.value === undefined) {\n      // Unknown or rejected: hand the line to the native slash pipeline.\n      insertCommand(document, `/${name} `)\n    }\n  } catch {\n    insertCommand(document, `/${name} `)\n  }\n}\n\n/** The host command catalog for the current session, exposed as palette commands. */\nfunction commandActions(host: SpotlightHost, document: Document): Promise<SpotlightAction[]> {\n  const commands = host.commands\n  if (commands === undefined) return Promise.resolve([])\n  const sessionId = host.sessions.list.getSnapshot().current\n  if (sessionId === undefined) return Promise.resolve([])\n  return commands.list(sessionId).then(result => {\n    if (!result.ok) return []\n    return result.value.flatMap(descriptor => {\n      const name = descriptor.name.trim()\n      if (!COMMAND_NAME.test(name)) return []\n      return [{\n        id: `command:${name}`,\n        kind: 'command',\n        title: `/${name}`,\n        detail: descriptor.description?.trim() || 'Slash command',\n        keywords: [name, descriptor.description ?? ''],\n        run: () => { void runSlashCommand(host, document, descriptor, name) },\n      }]\n    })\n  }, () => [] as SpotlightAction[])\n}\n\n/** Compact a module specifier into a display name. */\nfunction pluginDisplayName(moduleName: string): string {\n  const unscoped = moduleName.startsWith('@') ? moduleName.slice(moduleName.indexOf('/') + 1) : moduleName\n  return unscoped.replace(new RegExp('^(?:cordis-plugin-|dsh-(?:host-|client-)?)'), '') || moduleName\n}\n\n/** Installed plugins from the host inventory, each jumping to the Plugins settings section. */\nfunction pluginActions(host: SpotlightHost, document: Document): Promise<SpotlightAction[]> {\n  const inventory = host.pluginInventory\n  if (inventory === undefined) return Promise.resolve([])\n  return inventory.list().then(result => {\n    if (!result.ok) return []\n    return result.value.entries.flatMap((entry: SpotlightPluginEntry) => {\n      const title = pluginDisplayName(entry.moduleName)\n      if (title === '') return []\n      return [{\n        id: `plugin:${entry.entryId}`,\n        kind: 'plugin',\n        title,\n        detail: `${entry.entryId}${entry.enabled ? '' : ' · 已禁用'}`,\n        keywords: [entry.entryId, entry.moduleName, '插件', 'plugin'],\n        run: () => { void openPluginSettings(document) },\n      }]\n    })\n  }, () => [] as SpotlightAction[])\n}\n\n/** Discover immediately available actions: built-ins, sessions, and interface elements. */\nexport function discoverVisibleActions(host: SpotlightHost, document: Document): SpotlightAction[] {\n  return unique([\n    ...builtInActions(document),\n    ...sessionActions(host),\n    ...interfaceActions(document),\n  ])\n}\n\n/** Discover the full action set: visible actions plus the host command and plugin catalogs. */\nexport async function discoverActions(host: SpotlightHost, document: Document): Promise<SpotlightAction[]> {\n  const visible = discoverVisibleActions(host, document)\n  const [commands, plugins] = await Promise.all([\n    commandActions(host, document),\n    pluginActions(host, document),\n  ])\n  return unique([...visible, ...commands, ...plugins])\n}\n"
    },
    {
      "path": "src/spotlight/search.ts",
      "content": "/** Searchable metadata shared by browser actions. */\nexport interface SearchCandidate {\n  id: string\n  kind: 'action' | 'command' | 'session' | 'plugin'\n  title: string\n  detail?: string\n  keywords?: readonly string[]\n}\n\n/** One candidate plus its deterministic relevance score. */\nexport interface RankedCandidate<T extends SearchCandidate> {\n  item: T\n  score: number\n}\n\nfunction normalize(value: string): string {\n  return value.normalize('NFKC').toLocaleLowerCase().replace(new RegExp('\\\\s+', 'g'), ' ').trim()\n}\n\nfunction subsequenceScore(haystack: string, needle: string): number {\n  let cursor = 0\n  let first = -1\n  let gaps = 0\n  for (const char of needle) {\n    const next = haystack.indexOf(char, cursor)\n    if (next < 0) return -1\n    if (first < 0) first = next\n    gaps += next - cursor\n    cursor = next + 1\n  }\n  return 120 - first * 2 - gaps\n}\n\nfunction tokenScore(title: string, haystack: string, token: string): number {\n  if (title === token) return 1_000\n  if (title.startsWith(token)) return 800 - title.length\n  const titleIndex = title.indexOf(token)\n  if (titleIndex >= 0) return 600 - titleIndex\n  const textIndex = haystack.indexOf(token)\n  if (textIndex >= 0) return 400 - textIndex\n  return subsequenceScore(haystack, token)\n}\n\n/** Score a candidate. Negative values mean no match. */\nexport function scoreCandidate(candidate: SearchCandidate, query: string): number {\n  const normalizedQuery = normalize(query)\n  if (normalizedQuery === '') return 0\n  const title = normalize(candidate.title)\n  const haystack = normalize([\n    candidate.title,\n    candidate.detail ?? '',\n    ...(candidate.keywords ?? []),\n  ].join(' '))\n  let score = 0\n  for (const token of normalizedQuery.split(' ')) {\n    const value = tokenScore(title, haystack, token)\n    if (value < 0) return -1\n    score += value\n  }\n  return score\n}\n\n/**\n * Display cap over an already-ranked list: keep at most `perKind` candidates\n * per kind in rank order. The underlying candidate set stays uncapped, so a\n * query can still surface anything the cap hides in the initial view.\n */\nexport function capPerKind<T extends SearchCandidate>(\n  ranked: readonly RankedCandidate<T>[],\n  perKind: number,\n): RankedCandidate<T>[] {\n  const counts = new Map<T['kind'], number>()\n  return ranked.filter(({ item }) => {\n    const current = counts.get(item.kind) ?? 0\n    if (current >= perKind) return false\n    counts.set(item.kind, current + 1)\n    return true\n  })\n}\n\n/** Rank matching candidates while preserving discovery order for equal scores. */\nexport function searchCandidates<T extends SearchCandidate>(\n  candidates: readonly T[],\n  query: string,\n  limit = 12,\n): RankedCandidate<T>[] {\n  if (!Number.isSafeInteger(limit) || limit < 1) throw new RangeError('search limit must be a positive integer')\n  return candidates\n    .map((item, order) => ({ item, order, score: scoreCandidate(item, query) }))\n    .filter(result => result.score >= 0)\n    .sort((a, b) => b.score - a.score || a.order - b.order)\n    .slice(0, limit)\n    .map(({ item, score }) => ({ item, score }))\n}\n"
    },
    {
      "path": "src/spotlight/mount.ts",
      "content": "import { discoverActions, discoverVisibleActions, type SpotlightAction } from './discovery.ts'\nimport type { SpotlightHost } from './host.ts'\nimport {\n  defaultShortcut, formatShortcut, isSpotlightShortcut, moveSelection, parseShortcut, shortcutFromEvent,\n  type SpotlightShortcut,\n} from './keyboard.ts'\nimport { capPerKind, searchCandidates } from './search.ts'\n\nconst STYLE_ID = 'dsh-spotlight-style'\nconst ROOT_ATTRIBUTE = 'data-dsh-spotlight-root'\nconst SHORTCUT_STORAGE_KEY = 'dsh.spotlight.shortcut.v1'\nconst KIND_LABEL: Record<SpotlightAction['kind'], string> = {\n  action: '操作', command: '命令', session: '会话', plugin: '插件',\n}\n\n/** The palette consumes the host theme's alias tokens so it follows light/dark and brand overrides. */\nconst CSS = `\n[data-dsh-spotlight-root] { position: fixed; inset: 0; z-index: 2147483000; display: grid; place-items: start center; padding-top: min(14vh, 120px); background: rgba(8, 10, 16, .48); backdrop-filter: blur(6px); font-family: ui-sans-serif, system-ui, -apple-system, sans-serif; }\n[data-dsh-spotlight-panel] { width: min(680px, calc(100vw - 28px)); max-height: min(620px, calc(100vh - 48px)); overflow: hidden; border: 1px solid var(--dsw-alias-border-l1, rgba(255,255,255,.12)); border-radius: 18px; background: var(--dsw-alias-bg-overlay, #17191f); color: var(--dsw-alias-label-primary, #f5f7fb); box-shadow: 0 24px 80px rgba(0,0,0,.42); }\n[data-dsh-spotlight-search] { display: flex; align-items: center; gap: 12px; padding: 18px 18px 14px; border-bottom: 1px solid var(--dsw-alias-border-l1, rgba(255,255,255,.1)); }\n[data-dsh-spotlight-search] svg { width: 20px; height: 20px; flex: none; color: var(--dsw-alias-label-secondary, #949aa8); }\n[data-dsh-spotlight-input] { width: 100%; border: 0; outline: 0; background: transparent; color: inherit; font: inherit; font-size: 17px; line-height: 1.5; }\n[data-dsh-spotlight-input]::placeholder { color: var(--dsw-alias-label-secondary, #8f96a3); }\n[data-dsh-spotlight-results] { max-height: min(470px, calc(100vh - 190px)); overflow: auto; padding: 8px; }\n[data-dsh-spotlight-option] { width: 100%; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 12px; align-items: center; padding: 11px 12px; border: 0; border-radius: 11px; background: transparent; color: inherit; text-align: left; cursor: pointer; }\n[data-dsh-spotlight-option][aria-selected=\"true\"], [data-dsh-spotlight-option]:hover { background: color-mix(in srgb, var(--dsw-alias-brand-primary, #4d6bfe) 16%, transparent); }\n[data-dsh-spotlight-title] { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 14px; font-weight: 620; }\n[data-dsh-spotlight-detail] { display: block; margin-top: 3px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--dsw-alias-label-secondary, #969dab); font-size: 12px; }\n[data-dsh-spotlight-kind] { padding: 3px 7px; border: 1px solid var(--dsw-alias-border-l1, rgba(255,255,255,.12)); border-radius: 999px; color: var(--dsw-alias-label-secondary, #a1a7b3); font-size: 11px; }\n[data-dsh-spotlight-empty] { padding: 42px 18px; color: var(--dsw-alias-label-secondary, #969dab); text-align: center; font-size: 13px; }\n[data-dsh-spotlight-footer] { display: flex; justify-content: space-between; gap: 12px; padding: 10px 16px 12px; border-top: 1px solid var(--dsw-alias-border-l1, rgba(255,255,255,.08)); color: var(--dsw-alias-label-secondary, #8f96a3); font-size: 11px; }\n[data-dsh-spotlight-footer] kbd { padding: 2px 5px; border: 1px solid var(--dsw-alias-border-l1, rgba(255,255,255,.14)); border-radius: 5px; background: rgba(255,255,255,.04); font: inherit; }\n[data-dsh-spotlight-footer-controls] { display: flex; align-items: center; gap: 10px; }\n[data-dsh-spotlight-shortcut], [data-dsh-spotlight-shortcut-reset] { border: 0; padding: 0; background: transparent; color: inherit; font: inherit; cursor: pointer; }\n[data-dsh-spotlight-shortcut]:hover, [data-dsh-spotlight-shortcut-reset]:hover { color: var(--dsw-alias-label-primary, #f5f7fb); }\n[data-dsh-spotlight-shortcut][data-recording=\"true\"] { color: var(--dsw-alias-label-primary, #f5f7fb); }\n@media (prefers-reduced-motion: no-preference) { [data-dsh-spotlight-panel] { animation: dsh-spotlight-in .12s ease-out; } @keyframes dsh-spotlight-in { from { opacity: 0; transform: translateY(-8px) scale(.985); } } }\n`\n\nfunction icon(document: Document): SVGElement {\n  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg')\n  svg.setAttribute('viewBox', '0 0 24 24')\n  svg.setAttribute('aria-hidden', 'true')\n  const path = document.createElementNS('http://www.w3.org/2000/svg', 'path')\n  path.setAttribute('fill', 'none')\n  path.setAttribute('stroke', 'currentColor')\n  path.setAttribute('stroke-width', '2')\n  path.setAttribute('stroke-linecap', 'round')\n  path.setAttribute('d', 'm21 21-4.3-4.3m2.3-5.2a7.5 7.5 0 1 1-15 0 7.5 7.5 0 0 1 15 0Z')\n  svg.appendChild(path)\n  return svg\n}\n\n/** Mount the browser contribution and return its disposer plus a programmatic opener. */\nexport function mountSpotlight(host: SpotlightHost, document: Document, window: Window): {\n  dispose(): void\n  open(): void\n} {\n  const body = document.body\n  if (body === null) return { dispose: () => undefined, open: () => undefined }\n\n  let ownsStyle = false\n  if (document.getElementById(STYLE_ID) === null) {\n    const style = document.createElement('style')\n    style.id = STYLE_ID\n    style.textContent = CSS\n    document.head.appendChild(style)\n    ownsStyle = true\n  }\n\n  let root: HTMLElement | undefined\n  let previousFocus: HTMLElement | undefined\n  let recordingShortcut = false\n  const applePlatform = new RegExp('Mac|iPhone|iPad', 'i').test(window.navigator.platform)\n  const fallbackShortcut = defaultShortcut(applePlatform)\n  let shortcut: SpotlightShortcut = fallbackShortcut\n  try {\n    shortcut = parseShortcut(JSON.parse(window.localStorage.getItem(SHORTCUT_STORAGE_KEY) ?? 'null')) ?? fallbackShortcut\n  } catch {}\n\n  const saveShortcut = (next: SpotlightShortcut | undefined): void => {\n    shortcut = next ?? fallbackShortcut\n    try {\n      if (next === undefined) window.localStorage.removeItem(SHORTCUT_STORAGE_KEY)\n      else window.localStorage.setItem(SHORTCUT_STORAGE_KEY, JSON.stringify(next))\n    } catch {}\n  }\n\n  const close = (): void => {\n    recordingShortcut = false\n    root?.remove()\n    root = undefined\n    if (previousFocus?.isConnected === true) previousFocus.focus({ preventScroll: true })\n    previousFocus = undefined\n  }\n\n  const open = (): void => {\n    if (root !== undefined) return\n    document.querySelector<HTMLElement>(`[${ROOT_ATTRIBUTE}]`)?.remove()\n    previousFocus = document.activeElement instanceof HTMLElement ? document.activeElement : undefined\n\n    const overlay = document.createElement('div')\n    overlay.setAttribute(ROOT_ATTRIBUTE, '')\n    overlay.setAttribute('role', 'dialog')\n    overlay.setAttribute('aria-modal', 'true')\n    overlay.setAttribute('aria-label', 'DSH Spotlight')\n\n    const panel = document.createElement('section')\n    panel.setAttribute('data-dsh-spotlight-panel', '')\n    const search = document.createElement('div')\n    search.setAttribute('data-dsh-spotlight-search', '')\n    search.appendChild(icon(document))\n    const input = document.createElement('input')\n    input.type = 'text'\n    input.placeholder = '搜索操作、命令、会话或插件…'\n    input.autocomplete = 'off'\n    input.spellcheck = false\n    input.setAttribute('data-dsh-spotlight-input', '')\n    input.setAttribute('role', 'combobox')\n    input.setAttribute('aria-autocomplete', 'list')\n    input.setAttribute('aria-expanded', 'true')\n    input.setAttribute('aria-controls', 'dsh-spotlight-results')\n    search.appendChild(input)\n\n    const results = document.createElement('div')\n    results.id = 'dsh-spotlight-results'\n    results.setAttribute('data-dsh-spotlight-results', '')\n    results.setAttribute('role', 'listbox')\n    const footer = document.createElement('footer')\n    footer.setAttribute('data-dsh-spotlight-footer', '')\n    const count = document.createElement('span')\n    const controls = document.createElement('span')\n    controls.setAttribute('data-dsh-spotlight-footer-controls', '')\n    const shortcutButton = document.createElement('button')\n    shortcutButton.type = 'button'\n    shortcutButton.setAttribute('data-dsh-spotlight-shortcut', '')\n    shortcutButton.setAttribute('aria-label', '设置 Spotlight 快捷键')\n    const resetShortcut = document.createElement('button')\n    resetShortcut.type = 'button'\n    resetShortcut.setAttribute('data-dsh-spotlight-shortcut-reset', '')\n    resetShortcut.setAttribute('aria-label', '恢复默认快捷键')\n    resetShortcut.textContent = '恢复默认'\n    const help = document.createElement('span')\n    help.innerHTML = '<kbd>↑↓</kbd> 选择&nbsp;&nbsp;<kbd>↵</kbd> 执行&nbsp;&nbsp;<kbd>esc</kbd> 关闭'\n    controls.append(shortcutButton, resetShortcut, help)\n    footer.append(count, controls)\n    panel.append(search, results, footer)\n    overlay.appendChild(panel)\n    body.appendChild(overlay)\n    root = overlay\n\n    let actions: SpotlightAction[] = []\n    try {\n      actions = discoverVisibleActions(host, document)\n    } catch (error) {\n      console.warn('[dsh-spotlight] visible discovery failed', error)\n    }\n    let matches = searchCandidates(actions, '')\n    let active = matches.length > 0 ? 0 : -1\n\n    const renderShortcut = (): void => {\n      shortcutButton.textContent = recordingShortcut\n        ? '请按新快捷键…'\n        : `快捷键 ${formatShortcut(shortcut, applePlatform)}`\n      shortcutButton.setAttribute('data-recording', String(recordingShortcut))\n    }\n\n    shortcutButton.addEventListener('click', () => {\n      recordingShortcut = true\n      renderShortcut()\n      shortcutButton.focus({ preventScroll: true })\n    })\n    shortcutButton.addEventListener('keydown', event => {\n      event.preventDefault()\n      event.stopPropagation()\n      if (event.key === 'Escape') {\n        recordingShortcut = false\n        renderShortcut()\n        input.focus({ preventScroll: true })\n        return\n      }\n      const next = shortcutFromEvent(event)\n      if (next === undefined) return\n      saveShortcut(next)\n      recordingShortcut = false\n      renderShortcut()\n      input.focus({ preventScroll: true })\n    })\n    resetShortcut.addEventListener('click', () => {\n      saveShortcut(undefined)\n      recordingShortcut = false\n      renderShortcut()\n      input.focus({ preventScroll: true })\n    })\n\n    const execute = (action: SpotlightAction): void => {\n      close()\n      action.run()\n    }\n\n    const render = (): void => {\n      matches = capPerKind(searchCandidates(actions, input.value, 200), 6)\n      if (active >= matches.length) active = matches.length - 1\n      if (active < 0 && matches.length > 0) active = 0\n      results.textContent = ''\n      if (matches.length === 0) {\n        const empty = document.createElement('div')\n        empty.setAttribute('data-dsh-spotlight-empty', '')\n        empty.textContent = '没有匹配结果'\n        results.appendChild(empty)\n        input.removeAttribute('aria-activedescendant')\n      } else {\n        matches.forEach(({ item }, index) => {\n          const option = document.createElement('button')\n          option.type = 'button'\n          option.id = `dsh-spotlight-option-${index}`\n          option.setAttribute('data-dsh-spotlight-option', '')\n          option.setAttribute('role', 'option')\n          const copy = document.createElement('span')\n          const title = document.createElement('span')\n          title.setAttribute('data-dsh-spotlight-title', '')\n          title.textContent = item.title\n          const detail = document.createElement('span')\n          detail.setAttribute('data-dsh-spotlight-detail', '')\n          detail.textContent = item.detail ?? ''\n          copy.append(title, detail)\n          const kind = document.createElement('span')\n          kind.setAttribute('data-dsh-spotlight-kind', '')\n          kind.textContent = KIND_LABEL[item.kind]\n          option.append(copy, kind)\n          option.addEventListener('mousemove', () => {\n            if (active !== index) { active = index; render() }\n          })\n          option.addEventListener('click', () => { execute(item) })\n          results.appendChild(option)\n        })\n        input.setAttribute('aria-activedescendant', `dsh-spotlight-option-${active}`)\n      }\n      count.textContent = `${matches.length} 个结果`\n    }\n\n    input.addEventListener('input', () => { active = 0; render() })\n    input.addEventListener('keydown', event => {\n      if (event.key === 'Escape') { event.preventDefault(); close(); return }\n      if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {\n        event.preventDefault()\n        active = moveSelection(active, matches.length, event.key === 'ArrowDown' ? 1 : -1)\n        render()\n        document.getElementById(`dsh-spotlight-option-${active}`)?.scrollIntoView({ block: 'nearest' })\n        return\n      }\n      if (event.key === 'Enter' && active >= 0) {\n        event.preventDefault()\n        const action = matches[active]?.item\n        if (action !== undefined) execute(action)\n      }\n    })\n    overlay.addEventListener('mousedown', event => { if (event.target === overlay) close() })\n    render()\n    renderShortcut()\n    input.focus({ preventScroll: true })\n    void discoverActions(host, document).then(discovered => {\n      if (root !== overlay) return\n      actions = discovered\n      active = 0\n      render()\n      input.focus({ preventScroll: true })\n    }).catch(error => {\n      console.warn('[dsh-spotlight] async discovery failed', error)\n    })\n  }\n\n  const onGlobalKeydown = (event: KeyboardEvent): void => {\n    if (recordingShortcut || !isSpotlightShortcut(event, shortcut)) return\n    event.preventDefault()\n    event.stopPropagation()\n    if (root === undefined) open()\n    else close()\n  }\n  window.addEventListener('keydown', onGlobalKeydown, true)\n\n  const dispose = (): void => {\n    window.removeEventListener('keydown', onGlobalKeydown, true)\n    close()\n    if (ownsStyle) document.getElementById(STYLE_ID)?.remove()\n  }\n\n  return { dispose, open }\n}\n"
